/** Detect the initial locale: saved choice -> browser/system language -> default 'vi'. */
export function detectLocale(): Locale {
  if (typeof window === 'undefined') return 'vi';
  /**
   * `?lang=` THẮNG tất cả — đúng thứ tự máy chủ dùng (apps/web/src/lib/serverLocale.ts).
   *
   * Thiếu vế này thì hai phía nói hai thứ tiếng trên CÙNG một trang: máy chủ đọc `?lang=en` và
   * dựng ra tiếng Anh, còn trình duyệt lấy ngôn ngữ máy (tiếng Việt) rồi vẽ đè lên. Đo ngày
   * 23/09/2026 trên /blog?lang=en: 47 đoạn chữ tiếng Việt, gồm cả màn mở đầu và menu — những thứ
   * đã được dịch tử tế, chỉ là bị hỏi bằng sai ngôn ngữ.
   *
   * Đây cũng chính là địa chỉ hreflang khai cho bản tiếng Anh, nên máy tìm kiếm nào chạy JS sẽ
   * thấy một trang tự mâu thuẫn.
   */
  try {
    const q = new URLSearchParams(window.location.search).get('lang');
    if (q === 'vi' || q === 'en') return q;
  } catch {
    /* ignore */
  }
  /**
   * Rồi tới COOKIE — vì đó chính là thứ máy chủ vừa đọc để dựng trang này.
   *
   * localStorage thì máy chủ không thấy. Ai từng bấm đổi sang tiếng Anh sẽ có cả hai, nhưng hai
   * cái đó có thể lệch: cookie hết hạn sớm hơn, hoặc người dùng mở trang bằng `?lang=` ở tab khác.
   * Hỏi cookie trước localStorage nghĩa là phía trình duyệt luôn trả lời đúng bằng thứ tiếng mà
   * máy chủ vừa dùng, nên không bao giờ có cảnh trang vẽ lại sang tiếng khác sau khi đã hiện.
   */
  /**
   * 07/10/2026: mặc định là TIẾNG VIỆT khi người dùng chưa từng tự chọn — không còn đoán theo
   * ngôn ngữ máy. Máy cài macOS tiếng Anh (rất phổ biến ở VN) trước đây được phát hiện là 'en',
   * mà bản dịch tiếng Anh mới phủ một phần → thanh bên/tiêu đề tiếng Anh, thân trang tiếng Việt.
   *
   * "Đã tự chọn" = có giá trị trong localStorage: chỉ `setLocale` (nút VI/EN) ghi vào đó. Cookie
   * thì KHÔNG đủ làm bằng chứng: bản cũ tự ghi cookie ngay lần mở đầu tiên theo ngôn ngữ đoán được,
   * nên một cookie 'en' không kèm localStorage là dấu vết của lần đoán, không phải một lựa chọn.
   * Khi đã chọn thì vẫn hỏi cookie trước (lý do ở trên: khớp với thứ máy chủ vừa dùng).
   */
  let saved: string | null = null;
  try {
    saved = localStorage.getItem(STORAGE_KEY);
  } catch {
    /* ignore */
  }
  if (saved !== 'vi' && saved !== 'en') return 'vi';
  try {
    const m = document.cookie.match(new RegExp('(?:^|; )' + STORAGE_KEY + '=(vi|en)(?:;|$)'));
    if (m) return m[1] as Locale;
  } catch {
    /* ignore */
  }
  return saved;
}

/**
 * Dịch MỘT khoá theo ngôn ngữ chỉ định, không cần context.
 *
 * Có để những trang kết xuất ở MÁY CHỦ truyền xuống đúng thứ tiếng máy chủ đã chọn. `useI18n` thì
 * không dùng được ở đó: trước khi trình duyệt chạy, context luôn là 'vi', nên khung trang (menu,
 * chân trang, màn mở đầu) ra tiếng Việt trong HTML đầu tiên rồi mới đổi sang tiếng Anh sau khi
 * hydrate — người dùng thấy chữ nhảy, còn máy tìm kiếm đọc HTML thô thì thấy một trang tiếng Việt
 * mang thẻ hreflang khai là tiếng Anh.
 */
export function translate(
  locale: Locale,
  key: string,
  fallback?: string,
  vars?: Record<string, string | number>,
): string {
  return interpolate(MESSAGES[key]?.[locale] ?? MESSAGES[key]?.vi ?? fallback ?? key, vars);
}

interface I18nCtx {
  locale: Locale;
  setLocale: (l: Locale) => void;
  t: (key: string, fallback?: string, vars?: Record<string, string | number>) => string;
}

const Ctx = createContext<I18nCtx | null>(null);

function interpolate(s: string, vars?: Record<string, string | number>): string {
  if (!vars) return s;
  let out = s;
  for (const k of Object.keys(vars)) out = out.split('{' + k + '}').join(String(vars[k]));
  return out;
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>('vi');
  useEffect(() => {
    const l = detectLocale();
    setLocaleState(l);
    try {
      document.documentElement.lang = l;
      /**
       * Ghi cookie ngay lần đầu, không đợi người dùng bấm đổi ngôn ngữ.
       *
       * Ai đã chọn tiếng Anh từ trước thì lựa chọn đó nằm trong localStorage và KHÔNG có cookie —
       * máy chủ vẫn trả tiếng Việt cho tới khi họ tình cờ bấm đổi ngôn ngữ lần nữa. Ghi ở đây là
       * để họ không phải làm gì cả.
       */
      document.cookie = `${STORAGE_KEY}=${l}; path=/; max-age=31536000; samesite=lax`;
    } catch { /* ignore */ }
  }, []);
  const setLocale = useCallback((l: Locale) => {
    setLocaleState(l);
    try {
      localStorage.setItem(STORAGE_KEY, l);
      document.documentElement.lang = l;
      /**
       * GHI THÊM COOKIE, không thay localStorage.
       *
       * localStorage chỉ có ở trình duyệt. Những trang kết xuất ở MÁY CHỦ — blog và bài viết —
       * không đọc được nó, nên dù người dùng đã chuyển site sang tiếng Anh thì HTML máy chủ trả
       * về vẫn là tiếng Việt. Đó đúng là lỗi vừa gặp: giao diện tiếng Anh mà bài vẫn tiếng Việt.
       *
       * Cookie thì đi kèm mọi yêu cầu nên máy chủ đọc được. Giữ cả hai: localStorage cho phần
       * client vốn đã dùng nó, cookie cho phần máy chủ.
       *
       * SameSite=Lax để cookie vẫn gửi khi người ta bấm link từ nơi khác vào — đúng lúc cần nhất.
       * Không đặt Secure vì còn chạy http ở máy phát triển; đây là lựa chọn ngôn ngữ, không phải
       * dữ liệu nhạy cảm.
       */
      document.cookie = `${STORAGE_KEY}=${l}; path=/; max-age=31536000; samesite=lax`;
    } catch { /* ignore */ }
  }, []);
  const t = useCallback(
    (key: string, fallback?: string, vars?: Record<string, string | number>) =>
      interpolate(MESSAGES[key]?.[locale] ?? MESSAGES[key]?.vi ?? fallback ?? key, vars),
    [locale],
  );
  const value = useMemo(() => ({ locale, setLocale, t }), [locale, setLocale, t]);
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

/** Access the current locale + t(). Safe outside a provider (falls back to Vietnamese). */
export function useI18n(): I18nCtx {
  const ctx = useContext(Ctx);
  if (ctx) return ctx;
  return {
    locale: 'vi',
    setLocale: () => undefined,
    t: (key: string, fallback?: string, vars?: Record<string, string | number>) =>
      interpolate(MESSAGES[key]?.vi ?? fallback ?? key, vars),
  };
}
